/* 7DOC 2.1 · buildless, device-local book companion. */
(() => {
  'use strict';
  const C = window.SevenCore, IX = window.SevenInteractions, $ = s => document.querySelector(s);
  const esc = x => String(x ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let updateManager=null,updateReloadLock=false,releaseShown=false,importBusy=false;
  let state, storageOK = true, recovery = null, migrated = false, route, activeArchive = null;
  let audio, audioDay = null, lastAudioSave = 0, dialogReturn = null, toastTimer, offlineBusy = false;
  let breathElapsed = 0, breathStart = 0, breathRunning = false, breathFrame = 0;
  let newInstallPrompt = null, importCandidate = null;
  const selectedRatings = new Set(), offlineDays = new Set();
  let renderedRoute = null, activationRunning = false, activationStart = 0, activationElapsed = 0, activationFrame = 0;
  const scrollPositions = new Map();
  const L = (de,en) => state.settings.language === 'de' ? de : en;
  const day = n => window.DAYS[state.settings.language][n-1];
  const record = n => state.days[n-1];
  const ids = () => C.allowed(state);
  const metricNames = () => L(['Klarheit','Ruhe','Energie','Selbstvertrauen'],['Clarity','Calm','Energy','Self-trust']);
  const stages = () => L(['Ankommen','Praxis','Reflexion','Ausklang'],['Arrive','Practice','Reflect','Close']);
  const dayLabel = n => L('Tag ','Day ') + n;
  const status = d => d.completed ? L('Abgeschlossen','Completed') : d.startedAt || Object.values(d.notes).some(Boolean) ? L('Begonnen','Started') : L('Bereit für dich','Ready for you');
  const icon = (name,cls='') => {
    const paths = { home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>', book:'<path d="M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1Zm0 0v15"/>', leaf:'<path d="M20 3c-8-1-15 2-15 9a6 6 0 0 0 6 6c7 0 10-7 9-15ZM4 21l11-11"/>', settings:'<circle cx="12" cy="12" r="3"/><path d="m9 3-1 3-3 1-2 3 2 2-1 3 2 3 3-1 3 2 3-2 3 1 2-3-1-3 2-2-2-3-3-1-1-3Z"/>', arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>', check:'<path d="m5 12 4 4L19 6"/>', lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>', download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>', clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>', close:'<path d="m6 6 12 12M18 6 6 18"/>', moon:'<path d="M20.8 13.2A9 9 0 0 1 10.8 3.2a9 9 0 1 0 10 10Z"/>', sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v2m0 18v2M1 12h2m18 0h2M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>', pause:'<path d="M8 5v14M16 5v14"/>', audio:'<path d="M4 15v-3a8 8 0 0 1 16 0v3"/><rect x="2" y="12" width="5" height="8" rx="2"/><rect x="17" y="12" width="5" height="8" rx="2"/>', back:'<path d="M20 12H5m6-6-6 6 6 6"/>' };
    return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name] || paths.leaf}</svg>`;
  };
  const plant = () => `<svg class="botanical" viewBox="0 0 240 280" fill="none" aria-hidden="true"><circle cx="120" cy="140" r="100" stroke="currentColor" stroke-opacity=".12"/><circle cx="120" cy="140" r="78" stroke="currentColor" stroke-opacity=".1"/><path d="M119 241c1-52-9-104 15-180M120 195c-36 2-64-15-64-49 32-2 52 18 64 49Zm0-45c34 4 62-14 65-47-32-3-55 15-65 47Zm7-44c-26-1-43-21-39-47 26 2 39 19 39 47Zm8-39c19-8 29-28 21-49-21 7-29 26-21 49Z" stroke="currentColor" stroke-width="1.5"/><path d="M82 251h76" stroke="currentColor" stroke-opacity=".4"/></svg>`;
  const button = (label,action,cls='button',extra='') => `<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
  const goButton = (label,to,cls='button secondary') => button(label,'navigate',cls,`data-route="${to}"`);
  function get(k) { try { return localStorage.getItem(k); } catch { storageOK = false; return null; } }
  function boot() {
    $('#header').after($('#navigation'));
    const raw = get(C.KEY);
    if (raw) { try { state = C.normalize(JSON.parse(raw)); } catch { recovery = raw; state = C.fresh(); } }
    else { let keys=[]; try{keys=Object.keys(localStorage);}catch{} const m = C.migrate(get,keys); state = m.state; migrated = m.migrated; }
    // A REST key has no role in this version. Preserve user data, remove only this unsafe secret.
    try { localStorage.removeItem('7doc_os_key'); } catch { storageOK = false; }
    if (!recovery && storageOK) save(false);
    applyTheme();
    route = parseRoute();
    render(false);
    window.addEventListener('hashchange', () => { pauseActivation(); route = parseRoute(); render(); });
    document.addEventListener('click', handleClick);
    document.addEventListener('input', handleInput);
    document.addEventListener('change', handleChange);
    document.addEventListener('submit', handleSubmit);
    $('#dialog').addEventListener('close', () => { pauseBreath(); if (!$('#dialog').open && dialogReturn?.isConnected) dialogReturn.focus(); });
    $('#dialog').addEventListener('cancel',event=>{if(updateReloadLock)event.preventDefault();});
    $('#dialog').addEventListener('click', e => { if (e.target === $('#dialog')) { const r=e.target.getBoundingClientRect(); if(e.clientX<r.left || e.clientX>r.right || e.clientY<r.top || e.clientY>r.bottom) closeDialog(); } });
    window.addEventListener('beforeinstallprompt', e => { e.preventDefault(); newInstallPrompt = e; });
    document.addEventListener('visibilitychange', () => { if (document.hidden) { pauseBreath(); pauseActivation(); captureAudio(); } });
    window.addEventListener('pagehide', () => { pauseActivation(); captureAudio(); });
    if(window.visualViewport){const keyboard=()=>{document.body.classList.toggle('keyboard-open',window.innerHeight-window.visualViewport.height>150);};window.visualViewport.addEventListener('resize',keyboard);}
    window.addEventListener('online', () => { const b=$('#connection-label'); if(b)b.textContent=L('Online','Online'); });
    window.addEventListener('offline', () => { const b=$('#connection-label'); if(b)b.textContent=L('Offline','Offline'); });
    matchMedia('(prefers-color-scheme: dark)').addEventListener?.('change', () => { if(state.settings.theme==='system')applyTheme(); });
    setupWorker(); refreshOffline();
    if(migrated)toast(L('Deine bisherigen Einträge wurden übernommen.','Your previous entries have been preserved.'));
  }
  function save(announce = true) {
    if(updateReloadLock)return false;
    if (recovery) { storageWarning(); return false; }
    try { state.updatedAt = new Date().toISOString(); localStorage.setItem(C.KEY, JSON.stringify(state)); storageOK = true; $('#storage-warning').hidden = true; if(announce)announceSaved(); return true; }
    catch { storageOK = false; storageWarning(); return false; }
  }
  function storageWarning() {
    const el=$('#storage-warning'); if(!el)return;
    el.hidden=false; el.textContent = recovery ? L('Dein bisheriger Speicher konnte nicht gelesen werden. Öffne Einstellungen → Datenrettung. Die Originaldaten bleiben erhalten.','Your existing storage could not be read. Open Settings → Recovery. The original data is preserved.') : L('Der Gerätespeicher ist gerade nicht verfügbar. Sichere deine aktuellen Einträge unter Einstellungen, bevor du die App schließt.','Device storage is currently unavailable. Back up your current entries in Settings before closing the app.');
  }
  function announceSaved() { const el=$('#save-status'); if(el)el.textContent=L('Auf diesem Gerät gespeichert','Saved on this device'); }
  function toast(msg) { const e=$('#toast'); e.textContent=msg;e.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.hidden=true,4200); }
  function parseRoute() {
    const value=location.hash.slice(1); if(['today','program','journey','settings','summary'].includes(value))return value;
    if(/^day(?:10|[1-9])$/.test(value))return value;
    return 'today';
  }
  function navigate(to) {
    if(!['today','program','journey','settings','summary'].includes(to)&&!/^day(?:10|[1-9])$/.test(to))return;
    if(location.hash==='#'+to){route=to;render();}else location.hash=to;
  }
  function accessibleRoute() {
    if(route==='settings')return 'settings';
    if(!ids().length)return 'gate';
    if(route.startsWith('day')&&!ids().includes(Number(route.slice(3))))return 'locked';
    if(route==='summary'&&!C.allComplete(state))return 'journey';
    return route;
  }
  function themeControlData() {
    const dark=state.settings.theme==='dark'||state.settings.theme==='system'&&matchMedia('(prefers-color-scheme: dark)').matches;
    return {icon:dark?'sun':'moon',label:dark?L('Hell','Light'):L('Dunkel','Dark'),title:dark?L('Zur hellen Darstellung wechseln','Switch to light appearance'):L('Zur dunklen Darstellung wechseln','Switch to dark appearance')};
  }
  function themeControl() {
    const t=themeControlData();
    return button(icon(t.icon)+'<span>'+t.label+'</span>','theme-toggle','icon-button theme-toggle','id="theme-toggle" aria-label="'+t.title+'" title="'+t.title+'"');
  }
  function updateThemeControl() {
    const b=$('#theme-toggle');if(!b)return;const t=themeControlData();
    b.innerHTML=icon(t.icon)+'<span>'+t.label+'</span>';b.setAttribute('aria-label',t.title);b.setAttribute('title',t.title);
  }
  function applyTheme() {
    const dark=state.settings.theme==='dark'||state.settings.theme==='system'&&matchMedia('(prefers-color-scheme: dark)').matches;
    document.documentElement.dataset.theme=dark?'dark':'light';
    $('meta[name="theme-color"]').content=dark?'#24211e':'#FAF8F3';
    updateThemeControl();
  }
  function shell(actual) {
    document.documentElement.lang=state.settings.language;
    document.title=(actual.startsWith('day')?dayLabel(Number(actual.slice(3)))+' · ':'')+'7 Days of Change';
    $('.skip-link').textContent=L('Zum Inhalt','Skip to content');
    $('#header').innerHTML=`<a href="#today" class="brand"><img src="img/logo.png" width="42" height="42" alt=""><span><strong>7 Days of Change</strong><small>SASH & VENTURES</small></span></a><div class="header-right"><span class="header-motto">${L('Heimkehr zu dir selbst','A gentle return to yourself')}</span>${button(state.settings.language.toUpperCase(),'language','icon-button',`aria-label="${L('Sprache wechseln: English','Change language: Deutsch')}"`)}${themeControl()}</div>`;
    const nav=[['today','home',L('Heute','Today')],['program','book',L('Alle Tage','All days')],['journey','leaf',L('Meine Reise','My journey')],['settings','settings',L('Einstellungen','Settings')]];
    $('#navigation').innerHTML=nav.map(([r,i,label])=>`<a href="#${r}" ${r===actual || r==='program'&&actual.startsWith('day')?'aria-current="page"':''}>${icon(i)}<span>${label==='Einstellungen'?'Einstel&shy;lungen':label}</span></a>`).join('');
    $('#navigation').setAttribute('aria-label',L('Hauptnavigation','Main navigation'));
    $('#footer').innerHTML=`<div class="footer-top"><div class="footer-brand"><strong>7 Days of Change</strong><span>SASH & VENTURES</span><p>${L('Begleitung zum Buch. Übungen für deinen Alltag.','A book companion. Practices for everyday life.')}</p></div><nav class="footer-links" aria-label="${L('Weitere Links','More links')}"><a href="#program">${L('Alle Tage','All days')}</a><a href="#settings">${L('Einstellungen & Sicherung','Settings & backup')}</a><a href="https://sashandventures.com" target="_blank" rel="noopener noreferrer">sashandventures.com ↗</a></nav></div><div class="footer-note">${icon('leaf')}<p>${L('Bei therapeutischem Unterstützungsbedarf wende dich an qualifizierte Fachpersonen.','For therapeutic support, consult a qualified professional.')}</p></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Sascha Böhme · Sash & Ventures</span><span>${L('Vorabversion','Preview version')} ${window.SevenUpdates?.VERSION||'2.3'}</span></div>`;
    const gb=$('#grounding-button');gb.hidden=!ids().length||actual.startsWith('day');gb.innerHTML=icon('leaf')+`<span>${L('Pause','Pause')}</span>`;gb.setAttribute('aria-label',L('Pause und Orientierung mit den fünf Sinnen','Pause and orient with your five senses'));
    if(!storageOK||recovery)storageWarning();
  }
  function render(focus = true) {
    const actual=accessibleRoute(); if(renderedRoute)scrollPositions.set(renderedRoute,window.scrollY||0); shell(actual);
    if(audio && actual.startsWith('day') && Number(actual.slice(3))!==audioDay)audio.pause();
    const views={gate:renderGate,today:renderToday,program:renderProgram,journey:renderJourney,settings:renderSettings,summary:renderSummary,locked:renderLocked};
    $('#main').innerHTML=actual.startsWith('day')?renderDay(Number(actual.slice(3))):(views[actual]||renderToday)();
    mountAudio(actual);
    renderedRoute=actual;if(focus){$('#main').focus({preventScroll:true});window.scrollTo({top:scrollPositions.get(actual)||0,behavior:'instant'});}
  }
  function progress(records=state.days, selection=ids()) {
    const count=selection.filter(n=>records[n-1].completed).length, pct=selection.length?Math.round(count/selection.length*100):0;
    return `<div class="progress-label"><span>${L('Dein Weg','Your path')}</span><span>${count} / ${selection.length} ${L('Tage','days')}</span></div><div class="progress-track" role="progressbar" aria-label="${L('Abgeschlossene Tage','Completed days')}" aria-valuemin="0" aria-valuemax="${selection.length||1}" aria-valuenow="${count}"><span style="width:${pct}%"></span></div>`;
  }
  function renderGate() {
    return `<section class="gate-layout"><div class="gate-story"><span class="eyebrow">7 DAYS OF CHANGE</span><h1>${L('Ein wenig Raum.<br>Für dich.','A little space.<br>For yourself.')}</h1><p class="lead">${L('Dein Begleiter zum Buch. Für ruhige Momente, kleine Schritte und das, was du mitnehmen möchtest.','Your companion to the book. For quiet moments, small steps and what you want to carry forward.')}</p><div class="gate-plant">${plant()}</div><p class="small">${L('Atem · Ausrichtung · Alltag','Breath · Direction · Everyday life')}</p></div><div class="card gate-card"><span class="eyebrow">${L('DEIN ZUGANG','YOUR ACCESS')}</span><h2>${L('Schön, dass du hier bist.','Welcome. This space is yours.')}</h2><p>${L('Deinen Zugangscode findest du auf dem Beileger oder in deiner Kaufbestätigung.','Find your access code on your insert card or in your purchase confirmation.')}</p>${codeForm()}<div class="quiet-note">${icon('lock')}<p>${L('Deine Einträge bleiben in diesem Browser. Eine Sicherung kannst du jederzeit selbst herunterladen.','Your entries stay in this browser. You can download your own backup at any time.')}</p></div><details><summary>${L('Hilfe mit deinem Zugang','Help with your access')}</summary><p>${L('Prüfe den Code in deiner Kaufbestätigung. Groß- und Kleinschreibung sind gleichwertig. Bei Fragen findest du den Kontakt auf sashandventures.com.','Check the code in your purchase confirmation. Letter case does not matter. Contact details are available at sashandventures.com.')}</p><a href="https://sashandventures.com" target="_blank" rel="noopener noreferrer">${L('Zur Website','Visit website')} ↗</a></details></div></section>`;
  }
  function codeForm() { return `<form id="code-form"><label for="access-code">${L('Zugangscode','Access code')}</label><div class="code-row"><input id="access-code" name="code" required maxlength="100" autocomplete="off" autocapitalize="none" spellcheck="false"><button type="submit" class="button">${L('Freischalten','Unlock')} ${icon('arrow')}</button></div><p id="code-error" class="field-error" role="alert"></p></form>`; }
  function renderLocked() {return `<section class="empty-state card">${icon('lock')}<h1>${L('Hier geht deine Reise weiter.','Your journey continues here.')}</h1><p>${L('Dieser Tag gehört zu einem weiteren Programmbereich. Trage deinen passenden Zugangscode ein oder entdecke die Erweiterung.','This day belongs to another part of the program. Enter its access code or explore the extension.')}</p>${button(L('Code ergänzen','Add access code'),'add-code')}${extensionLink()}</section>`;}
  function extensionLink(){return `<a class="text-link" href="https://sashandventures.gumroad.com/l/${L('7doc-erweiterung-de','7doc-extension-en')}" target="_blank" rel="noopener noreferrer">${L('Tage 8–10 entdecken','Explore days 8–10')} ↗</a>`;}
  function renderToday() {
    const next=C.nextDay(state), done=C.allComplete(state), n=next||ids().at(-1), d=day(n), r=record(n), count=ids().filter(i=>record(i).completed).length;
    const latest=ids().filter(i=>record(i).startedAt).sort((a,b)=>Date.parse(record(b).startedAt)-Date.parse(record(a).startedAt))[0];
    return `<section class="page-intro"><span class="eyebrow">${L('DEIN MOMENT HEUTE','YOUR MOMENT TODAY')}</span><h1>${state.settings.name?L('Schön, dass du da bist, ','Welcome back, ')+esc(state.settings.name)+'.':L('Schön, dass du da bist.','A moment to come back to yourself.')}</h1><p>${done?L('Deine Übungen bleiben für dich erreichbar. Nimm mit, was dir im Alltag hilft.','Your practices remain here for you. Carry what helps into your everyday life.'):L('Du gehst in deinem Tempo. Ein kleiner Schritt findet heute seinen Platz.','Move at your own pace. Make room for one small step today.')}</p></section><section class="today-hero"><div class="hero-copy"><div class="pill">${icon(done?'check':'sun')}${done?L('Dein Programm ist abgeschlossen','Your program is complete'):dayLabel(n)+' · '+L('Dein nächster Schritt','Your next step')}</div><h2>${done?L('Was dich begleitet.','What stays with you.'):esc(d.title)}</h2><p>${done?L('Ein Blick auf deine Einträge und die Werkzeuge, die du gefunden hast.','Look back at your entries and the tools you have found.'):esc(d.goal)}</p><div class="hero-meta"><span class="hero-meta-item">${icon('clock')} ${L('Praxis ca. 20 Min','Practice about 20 min')}</span><span class="hero-meta-separator">·</span><span class="hero-meta-item">${icon('audio')} ${L('Audio ca. 4 Min','Audio about 4 min')}</span></div>${goButton(done?L('Meinen Rückblick öffnen','Open my reflection'):r.startedAt?L('Session fortsetzen','Continue session'):L('Session beginnen','Begin session'),done?'summary':'day'+n,'button primary')}${!done&&d.onthego?button(L('Heute nur ein kurzer Moment','A shorter moment today'),'short-session','text-link',`data-day="${n}"`):''}</div><div class="hero-art">${plant()}<span>${L('IN DEINEM TEMPO','AT YOUR OWN PACE')}</span></div></section><section class="dashboard-grid"><div class="card path-card">${progress()}<div class="day-dots">${Array.from({length:10},(_,i)=>{const j=i+1,can=ids().includes(j);return `<a href="#day${j}" class="day-dot ${record(j).completed?'is-done':''} ${j===next?'is-next':''} ${can?'':'is-locked'}" aria-label="${dayLabel(j)+': '+esc(day(j).title)+' · '+(can?status(record(j)):L('Zusätzlicher Zugang','Additional access'))}" ${j===next?'aria-current="step"':''}>${!can?icon('lock'):record(j).completed?icon('check'):j}</a>`;}).join('')}</div><p class="small">${count?L('Jeder abgeschlossene Tag ist ein Moment, den du dir gegeben hast.','Every completed day is a moment you gave yourself.'):L('Sieben Kerntage. Drei Tage zur Vertiefung. Dein Zugang bestimmt deinen Umfang.','Seven core days. Three days to go deeper. Your access determines your program.')}</p></div><div class="card book-card">${icon('book')}<div><h3>${L('Dein Buch bleibt an deiner Seite.','Keep your book close.')}</h3><p>${L('Hier findest du die Praxis und deine Notizen. Im Buch wartet die Vertiefung.','Find your practice and notes here. The book holds the fuller context.')}</p>${goButton(L('Alle Tage ansehen','Explore all days'),'program','text-link')}</div></div></section>${moodCheckin()}${discoveryCollection(state.days,true)}${toolbox()}${latest&&!done?`<div class="quiet-row"><span>${L('Deine Einträge sind auf diesem Gerät gespeichert.','Your entries are saved on this device.')}</span>${goButton(L('Sicherung & Einstellungen','Backup & settings'),'settings','text-link')}</div>`:''}${count===0?`<section class="rhythm"><span class="eyebrow">${L('DEIN TÄGLICHER RHYTHMUS','YOUR DAILY RHYTHM')}</span><div>${stages().map((s,i)=>`<span><small>0${i+1}</small>${s}</span>`).join('')}</div></section>`:''}`;
  }
  function moodCheckin(){const value=state.moods[C.localDate()];const labels=L(['Schwer','Gedämpft','Ausgeglichen','Gut','Sehr gut'],['Heavy','Low','Balanced','Good','Very good']);return `<section class="mood-strip"><div><span class="eyebrow">${L('EIN KURZER CHECK-IN','A QUICK CHECK-IN')}</span><h3>${L('Wie geht es dir heute?','How are you today?')}</h3><p class="small">${L('Freiwillig. Deine Momentaufnahme für diesen Kalendertag.','Optional. Your snapshot for this calendar day.')}</p></div><div class="mood-options" role="group" aria-label="${L('Stimmung heute','Mood today')}">${labels.map((label,i)=>button(`<span aria-hidden="true">${['☁','◔','◑','◕','☀'][i]}</span><small>${label}</small>`,'mood',value===i+1?'selected':'',`data-mood="${i+1}" aria-pressed="${value===i+1}"`)).join('')}</div></section>`;}
  function toolbox(){const d=record(7),tools=[d.notes.r0,d.notes.r1].filter(x=>x?.trim());return tools.length?`<section class="card toolbox"><span class="eyebrow">${L('MEINE WERKZEUGE','MY TOOLS')}</span><h2>${L('Das nehme ich mit.','What I carry forward.')}</h2>${tools.map(x=>`<p class="tool-line">${icon('leaf')}<span>${esc(x)}</span></p>`).join('')}</section>`:'';}
  function renderProgram() {
    return `<section class="page-intro"><span class="eyebrow">${L('DEIN PROGRAMM','YOUR PROGRAM')}</span><h1>${L('Ein Weg. Viele kleine Schritte.','One path. Many small steps.')}</h1><p>${L('Die Tage bauen aufeinander auf. Du kannst jederzeit zurückkehren und eine Übung wiederholen.','The days build on one another. You can return to any available practice at any time.')}</p></section><div class="program-progress card">${progress()}</div>${[0,1].map(part=>`<section class="program-section"><div class="section-heading"><div><span class="eyebrow">${part?L('VERTIEFUNG','GO DEEPER'):L('DAS FUNDAMENT','THE FOUNDATION')}</span><h2>${part?L('Drei Tage für deinen Alltag','Three days for everyday life'):L('Deine sieben Kerntage','Your seven core days')}</h2></div><span class="small">${part?'08 — 10':'01 — 07'}</span></div><div class="program-list">${window.DAYS[state.settings.language].slice(part?7:0,part?10:7).map(d=>{const r=record(d.num),can=ids().includes(d.num);return `<a class="program-day ${can?'':'locked'}" href="#day${d.num}"><span class="program-number">${String(d.num).padStart(2,'0')}</span><div><h3>${esc(d.title)}</h3><p>${esc(d.subtitle)}</p><span class="small">${can?status(r):L('Mit weiterem Zugang verfügbar','Available with additional access')}${offlineDays.has(d.num)?' · '+L('Offline-Audio gespeichert','Offline audio saved'):''}</span></div><span class="program-trailing">${can?icon(r.completed?'check':'arrow'):icon('lock')}</span></a>`;}).join('')}</div></section>`).join('')}<div class="quiet-row">${button(L('Weiteren Code eingeben','Enter another access code'),'add-code','text-link')}${!C.entitlements(state).bonus?extensionLink():''}</div>`;
  }
  function rich(html) {
    // Editorial content only. User notes always go through esc()/textarea.value.
    const template=document.createElement('template');template.innerHTML=String(html).replace(/\n\n/g,'<br><br>');
    const allowed=new Set(['STRONG','EM','BR','UL','OL','LI','P']);
    for(const node of [...template.content.querySelectorAll('*')]){
      if(!allowed.has(node.tagName)){node.replaceWith(...node.childNodes);continue;}
      for(const attr of [...node.attributes])node.removeAttribute(attr.name);
    }
    return template.innerHTML;
  }
  function practiceCopy(n,html){return rich(html).replace(/\[(Diesen Wert|this value|Wert|Value|value)\]/g,esc(record(n===3?2:n).value||L('deinen gewählten Wert','your chosen value')));}
  function noteField(n,key,label,rows=3) {return `<div class="form-field"><label for="note-${key}">${esc(label)}</label><textarea id="note-${key}" data-note="${key}" data-day="${n}" rows="${rows}" maxlength="100000" placeholder="${L('Deine Gedanken haben hier Platz …','Make room for your thoughts …')}">${esc(record(n).notes[key]||'')}</textarea></div>`;}
  function renderDay(n) {
    const d=day(n),r=record(n),stage=r.stage;
    return `<section class="session-heading"><a class="back-link" href="#program">${icon('back')}${L('Alle Tage','All days')}</a><div class="session-title"><div><span class="eyebrow">${dayLabel(n)} ${n>7?'· '+L('VERTIEFUNG','GO DEEPER'):''}</span><h1>${esc(d.title)}</h1><p>${esc(d.subtitle)}</p></div><span class="session-number">${String(n).padStart(2,'0')}</span></div></section><div class="session-context"><span>${icon('clock')}${r.mode==='short'?L('Kurze Praxis','Short practice'):L('Praxis ca. 20 Min','Practice about 20 min')}</span><span>${icon('book')}${n>7?L('Bonusbuch','Bonus book'):L('Buch','Book')} · ${L('Seite ','Page ')}${d.bookPage}</span><span id="save-status" role="status">${storageOK?L('Auf diesem Gerät gespeichert','Saved on this device'):L('Sicherung empfohlen','Backup recommended')}</span></div><nav class="phase-navigation" aria-label="${L('Abschnitte der Session','Session sections')}">${stages().map((name,i)=>button(`<span>${i+1}</span>${name}`,'stage',i===stage?'phase active':'phase',`data-stage="${i}" data-day="${n}" ${i===stage?'aria-current="step"':''}`)).join('')}</nav><aside class="session-support" aria-labelledby="session-support-title"><span class="session-support-icon">${icon('leaf')}</span><p><strong id="session-support-title">${L('Du darfst jederzeit pausieren.','You can pause at any time.')}</strong><span>${L('Wähle die Intensität, die heute zu dir passt.','Choose the intensity that feels right today.')}</span></p>${button(icon('pause')+'<span>'+L('Pause','Pause')+'</span>','grounding','ix-button session-support-action','aria-label="'+L('Pause und Orientierung öffnen','Open pause and grounding')+'"')}</aside>${renderAudioPanel(n)}<section class="session-body">${[renderArrival,renderPractice,renderReflection,renderClosing][stage](n)}</section><div class="session-controls">${sessionControls(n)}</div>`;
  }
  function renderArrival(n) {
    const d=day(n),r=record(n),vals=r.ratingDraft||r.ratings||{a:5,b:5,c:5,d:5};
    return `<div class="section-top"><span class="eyebrow">01 · ${L('ANKOMMEN','ARRIVE')}</span><h2>${L('Wie bist du gerade hier?','How are you arriving today?')}</h2><p>${esc(d.goal)}</p></div><div class="arrival-grid"><div><p>${L('Spüre den Boden unter deinen Füßen. Lass dir einen Moment Zeit. Wenn du magst, halte fest, wie es dir vor der Praxis geht.','Feel the ground beneath your feet. Give yourself a moment. If you like, record how you feel before the practice.')}</p><div class="checkin-card"><div class="section-heading"><h3>${L('Dein Check-in','Your check-in')}</h3><span class="small">${r.ratingDraft?L('Entwurf','Draft'):r.ratings?L('Bestätigt','Confirmed'):L('Freiwillig','Optional')}</span></div><p class="small">${L('0 = sehr wenig · 10 = sehr viel. Die Werte zählen erst nach deiner Bestätigung.','0 = very little · 10 = a lot. Values count only after you confirm them.')}</p>${C.METRICS.map((k,i)=>`<div class="rating-row"><label for="rating-${k}">${metricNames()[i]}</label><output for="rating-${k}" id="out-${k}">${vals[k]}</output><input type="range" id="rating-${k}" data-rating="${k}" min="0" max="10" step="1" value="${vals[k]}" aria-describedby="rating-explainer"></div>`).join('')}<p id="rating-explainer" class="small">${r.ratings?L('Du kannst deinen Check-in hier bewusst aktualisieren.','You can deliberately update your check-in here.'):L('Die Regler starten bei 5. Du entscheidest, ob du diese Werte speichern möchtest.','Sliders start at 5. You choose whether to save these values.')}</p>${button(r.ratings?L('Check-in aktualisieren','Update check-in'):L('Check-in speichern','Save check-in'),'save-ratings','button secondary',`data-day="${n}"`)}<span id="rating-feedback" role="status"></span></div>${r.legacyRatings?`<details><summary>${L('Bewertungen aus der bisherigen App','Ratings from the previous app')}</summary><p class="small">${L('Diese Werte sind übernommen. Weil die frühere App auch unbestätigte Startwerte verwendete, fließen sie erst nach deiner neuen Bestätigung in den Vergleich ein.','These values were preserved. The previous app also used unconfirmed defaults, so they enter comparisons only after you confirm a new check-in.')}</p>${ratingChips(r.legacyRatings)}</details>`:''}</div><aside><div class="soft-card"><span class="eyebrow">${L('DEIN RAHMEN','YOUR SPACE')}</span><h3>${L('Ein ruhiger Anfang.','A quiet beginning.')}</h3><ul class="preparation-list"><li>${L('Ein Platz, an dem du dich wohlfühlst.','A place where you feel comfortable.')}</li><li>${L('Wasser und etwas zum Schreiben.','Water and somewhere to write.')}</li><li>${L('Das Handy auf lautlos, wenn es passt.','Your phone on silent, if that works for you.')}</li></ul><a class="text-link" href="./Daily%20Routine%20Sheet%20-%20${state.settings.language.toUpperCase()}.pdf" target="_blank" rel="noopener">${L('Routine-Sheet öffnen','Open routine sheet')} ↗</a></div><details><summary>${L('Warum dieser Tag?','Why this day?')}</summary><div class="reading">${rich(d.intro)}</div></details></aside></div>`;
  }
  function ratingChips(values){return `<div class="rating-chips">${C.METRICS.map((k,i)=>`<span>${metricNames()[i]} <strong>${values[k]}<small>/10</small></strong></span>`).join('')}</div>`;}
  function practiceFields(n) {const legacy=n===2&&record(2).value&&!record(2).notes.ix_state;if(legacy)IX.patch(record(2).notes,{winner:record(2).value,compared:true,choices:[record(2).value]});return IX.render(n,{records:state.days,lang:state.settings.language,paper:state.settings.writingMode==='paper'}); }
  function renderPractice(n) {
    const d=day(n),r=record(n),step=r.practiceStep,st=d.steps[step];
    return `<div class="section-top"><span class="eyebrow">02 · ${L('PRAXIS','PRACTICE')}</span><h2>${L('Ein Schritt nach dem anderen.','One step at a time.')}</h2></div>${d.onthego?`<div class="mode-switch" role="group" aria-label="${L('Umfang der Praxis','Practice length')}">${button(L('Die ganze Praxis','Full practice'),'mode',r.mode==='full'?'selected':'',`data-mode="full" data-day="${n}" aria-pressed="${r.mode==='full'}"`)}${button(L('Ein kurzer Moment','A shorter moment'),'mode',r.mode==='short'?'selected':'',`data-mode="short" data-day="${n}" aria-pressed="${r.mode==='short'}"`)}</div>`:''}${r.mode==='short'&&d.onthego?`<div class="practice-card"><span class="eyebrow">${L('DEINE KURZE PRAXIS','YOUR SHORT PRACTICE')}</span>${d.onthego.map(([title,body],i)=>`<div class="short-step"><span>${i+1}</span><div><h3>${esc(title)}</h3><p>${rich(body)}</p></div></div>`).join('')}</div>`:`<nav class="practice-tabs" aria-label="${L('Übungsschritte','Practice steps')}">${d.steps.map((s,i)=>button(`<span>${i+1}</span>${esc(s.t)}`,'practice-step',i===step?'active':'',`data-step="${i}" data-day="${n}" ${i===step?'aria-current="step"':''}`)).join('')}</nav><article class="practice-card"><span class="eyebrow">${L('SCHRITT','STEP')} ${step+1} / 3</span><h2>${esc(st.t)}</h2><div class="reading">${practiceCopy(n,st.c)}</div>${step===1?practiceFields(n):''}${st.tips||st.opt?`<details><summary>${L('Hilfestellung für diesen Schritt','Help with this step')}</summary>${(st.tips||[]).map(t=>`<p>${rich(t)}</p>`).join('')}${st.opt?`<div class="reading">${rich(st.opt)}</div>`:''}</details>`:''}${st.box?`<div class="quiet-note"><p>${rich(st.box)}</p></div>`:''}</article>`}<details class="background-reading"><summary>${L('Hintergrund & Vertiefung im Buch','Background & further reading')}</summary><h3>${L('Was dahinter steckt','The background')}</h3><p>${rich(d.science)}</p><h3>${L('Was du mitnehmen kannst','What you can take with you')}</h3><p>${rich(d.benefit)}</p><p class="small">${L('Die Einordnung gehört zur Buchvorlage. Dein persönliches Erleben kann davon abweichen.','This context comes from the book. Your personal experience may differ.')}</p></details>`;
  }
  function valuePicker(n){const words=L(['Klarheit','Ruhe','Mut','Vertrauen','Verbindung','Fokus','Offenheit','Stärke','Geduld','Leichtigkeit','Präsenz','Dankbarkeit','Ehrlichkeit','Mitgefühl','Energie'],['Clarity','Calm','Courage','Trust','Connection','Focus','Openness','Strength','Patience','Ease','Presence','Gratitude','Honesty','Compassion','Energy']);return `<div class="value-picker"><label for="day-value">${L('Mein Wert heute','My value today')}</label><div class="value-options">${words.map(w=>button(esc(w),'value',record(n).value===w?'selected':'',`data-value="${esc(w)}" data-day="${n}" aria-pressed="${record(n).value===w}"`)).join('')}</div><input id="day-value" data-value-input="${n}" maxlength="80" value="${esc(record(n).value)}" placeholder="${L('Oder dein eigenes Wort','Or your own word')}"></div>`;}
  function renderReflection(n){const d=day(n);return `<div class="section-top"><span class="eyebrow">03 · ${L('REFLEXION','REFLECT')}</span><h2>${L('Was bleibt bei dir?','What stays with you?')}</h2><p>${L('Ein Wort oder ein paar Zeilen reichen. Du entscheidest, welche Fragen du aufnehmen möchtest.','A word or a few lines can be enough. Choose the questions you want to explore.')}</p></div><div class="reflection-card">${d.reflections.map((q,i)=>noteField(n,'r'+i,q)).join('')}${noteField(n,'step3note',L('Freier Raum für deine Gedanken','Open space for your thoughts'),5)}<p class="small">${L('Jede Eingabe wird direkt auf diesem Gerät gespeichert. Unter Einstellungen findest du die Sicherung.','Each entry is saved directly on this device. Find backups in Settings.')}</p></div>`;}
  function renderClosing(n){const r=record(n),selection=ids(),doneCount=selection.filter(i=>record(i).completed).length;return `<div class="closing-card"><div class="closing-symbol">${icon(r.completed?'check':'leaf')}</div><span class="eyebrow">04 · ${L('AUSKLANG','CLOSE')}</span><h2>${r.completed?L('Dieser Moment gehört dir.','This moment is yours.'):L('Nimm dir einen Moment.','Take a moment.')}</h2><p>${r.completed?L('Dein Tag ist abgeschlossen. Deine Notizen bleiben für dich erreichbar.','Your day is complete. Your notes remain here for you.'):L('Lass den Atem frei fließen. Spüre den Boden. Vielleicht magst du ein Glas Wasser trinken oder kurz ans Fenster gehen.','Let your breath flow freely. Feel the ground. Perhaps have a glass of water or step over to a window.')}</p>${r.ratings?ratingChips(r.ratings):`<p class="small">${L('Du hast heute die Praxis gewählt. Ein Check-in ist freiwillig.','You chose to practise today. A check-in is optional.')}</p>`}${r.completed?`<div class="closing-actions">${C.allComplete(state)?goButton(L('Meinen Rückblick ansehen','See my reflection'),'summary','button primary'):goButton(L('Zurück zu Heute','Back to Today'),'today','button primary')}${button(L('Abschluss zurücknehmen','Undo completion'),'undo-complete','text-link',`data-day="${n}"`)}</div>`:`${button(L('Tag abschließen','Complete day')+icon('check'),'complete','button primary',`data-day="${n}"`)}<p class="small">${doneCount+1} / ${selection.length} ${L('Tage deines Programms','days in your program')}</p>`}<div class="quiet-note"><p>${L('Du kannst jederzeit zurückkehren und diesen Tag wieder öffnen.','You can return to this day whenever you like.')}</p></div></div>`;}
  function journalCards(records,selection){return selection.map(n=>{const d=day(n),r=records[n-1],entries=Object.entries(r.notes).filter(([k,v])=>k!=='ix_state'&&v.trim());if(!r.completed&&!entries.length&&!r.ratings&&!r.value)return '';return `<details class="journal-day"><summary><span class="journal-number">${String(n).padStart(2,'0')}</span><span><strong>${esc(d.title)}</strong><small>${status(r)}${r.completedAt?' · '+new Date(r.completedAt).toLocaleDateString(state.settings.language==='de'?'de-DE':'en-GB'):''}</small></span>${icon(r.completed?'check':'book')}</summary><div class="journal-content">${r.ratings?ratingChips(r.ratings):''}${r.legacyRatings?`<p class="small">${L('Übernommene Bewertungen · außerhalb des neuen Vergleichs','Preserved ratings · excluded from new comparisons')}</p>${ratingChips(r.legacyRatings)}`:''}${r.value?`<p><strong>${L('Mein Wert','My value')}:</strong> ${esc(r.value)}</p>`:''}${entries.map(([k,v])=>`<div class="journal-entry"><h4>${esc(noteLabel(n,k))}</h4><p>${esc(v)}</p></div>`).join('')}${activeArchive===null?goButton(L('Tag wieder öffnen','Reopen day'),'day'+n,'text-link'):''}</div></details>`;}).join('');}
  function noteLabel(n,k){if(k==='ix_result')return L('Mein Fundstück','My discovery');if(k.startsWith('ix_'))return IX.fieldLabel(k,state.settings.language);if(/^r\d+$/.test(k))return day(n).reflections[Number(k.slice(1))]||L('Reflexion','Reflection');const names={step3note:L('Meine Notizen','My notes'),s2note:L('Die Situation','The situation'),story:L('Meine Geschichte','My story'),helpful:L('Eine hilfreiche Sicht','A helpful perspective'),bio:L('Körper & Raum','Body & space'),psycho:L('Gedanken','Mind'),social:L('Verbindung','Connection'),future_letter:L('Mein Brief aus der Zukunft','My letter from the future'),boundary:L('Meine bewusste Entscheidung','My deliberate choice'),new_sentence:L('Mein neuer Satz','My new sentence'),old_sentence:L('Mein bisheriger Satz','My previous sentence'),value_action:L('Mein Wert im Alltag','My value in everyday life'),activation:L('Meine Handlung','My action'),connection:L('Meine Verbindung','My connection')};return names[k]||L('Weitere Notiz','Additional note');}
  function insightPanel(records,selection){const ins=C.insights(records,selection);const messages={insufficient:L('Für einen Vergleich brauchst du bestätigte Check-ins an mindestens zwei Tagen. Deine Einträge sind auch für sich wertvoll.','A comparison needs confirmed check-ins on at least two days. Your entries are valuable on their own.'),stable:L('Deine ersten und letzten bestätigten Werte sind gleich. Wie sich die Zeit für dich angefühlt hat, erzählen deine Notizen.','Your first and last confirmed ratings are equal. Your notes can tell you more about how this time felt.'),higher:L('Deine letzten Werte liegen insgesamt höher oder gleichauf. Das beschreibt deine Selbsteinschätzung an diesen Tagen.','Your latest ratings are higher or unchanged overall. This describes your self-assessment on those days.'),lower:L('Deine letzten Werte liegen insgesamt niedriger oder gleichauf. Auch diese Wahrnehmung hat hier ihren Platz.','Your latest ratings are lower or unchanged overall. There is room for this experience here too.'),mixed:L('Deine Werte bewegen sich in verschiedene Richtungen. Schau in Ruhe darauf, was dir heute wichtig ist.','Your ratings move in different directions. Take a moment to notice what matters to you today.')};return `<section class="card insight-panel"><span class="eyebrow">${L('DEINE EINTRÄGE IM BLICK','YOUR ENTRIES AT A GLANCE')}</span><h2>${L('Wahrnehmen, was sich zeigt.','Notice what is here.')}</h2><p>${messages[ins.kind]}</p>${ins.deltas?`<p class="small">${dayLabel(ins.first)} → ${dayLabel(ins.last)} · ${ins.orderedBy==='time'?L('nach Zeitpunkt des Check-ins','by check-in time'):L('nach Tagesnummer, Datum unbekannt','by day number, date unknown')}</p><div class="insight-grid">${ins.deltas.map((v,i)=>`<div><span>${metricNames()[i]}</span><strong>${v>0?'+':''}${v}</strong><small>${L('Punkte Veränderung','points difference')}</small></div>`).join('')}</div>`:''}<p class="small">${L('Momentaufnahmen deiner eigenen Einschätzung. Daraus lässt sich die Wirkung einer einzelnen Übung nicht ableiten.','Snapshots of your own assessment. They do not establish the effect of any individual practice.')}</p></section>`;}
  function moodHistory(){const labels=L(['Schwer','Gedämpft','Ausgeglichen','Gut','Sehr gut'],['Heavy','Low','Balanced','Good','Very good']);const entries=Object.entries(state.moods).sort((a,b)=>b[0].localeCompare(a[0]));return entries.length?`<details class="mood-history"><summary>${L('Meine letzten Stimmungs-Check-ins','My recent mood check-ins')} · ${entries.length}</summary><p class="small">${L('Die letzten 14 Einträge, unabhängig vom Durchlauf. Alle Einträge sind in deiner Sicherung enthalten.','The latest 14 entries, across rounds. All entries are included in your backup.')}</p><ul>${entries.slice(0,14).map(([date,v])=>`<li><time datetime="${date}">${date}</time><span>${labels[v-1]}</span></li>`).join('')}</ul></details>`:'';}
  function renderJourney(){const a=activeArchive===null?null:state.archives[activeArchive],records=a?.days||state.days,selection=a?Array.from({length:10},(_,i)=>i+1):ids(),cards=journalCards(records,selection);return `<section class="page-intro"><span class="eyebrow">${L('MEINE REISE','MY JOURNEY')}</span><h1>${L('Dein Raum zum Zurückblicken.','Your space to look back.')}</h1><p>${L('Hier finden deine Gedanken, deine Praxis und deine Wahrnehmungen zusammen.','Here, your thoughts, practices and observations come together.')}</p></section>${state.archives.length?`<div class="archive-switch"><label for="archive-select">${L('Durchlauf','Round')}</label><select id="archive-select"><option value="current" ${!a?'selected':''}>${L('Mein aktueller Durchlauf','My current round')}</option>${state.archives.map((x,i)=>`<option value="${i}" ${activeArchive===i?'selected':''}>${L('Archiv','Archive')} ${i+1} · ${x.endedAt?new Date(x.endedAt).toLocaleDateString(state.settings.language==='de'?'de-DE':'en-GB'):''}</option>`).join('')}</select></div>`:''}${activeArchive!==null?`<div class="archive-actions">${button(L('Diesen Durchlauf sichern','Back up this round'),'backup-round','button secondary')}${button(L('Dieses Archiv entfernen','Remove this archive'),'archive-remove','text-link')}</div>`:''}${cards?`${discoveryCollection(records)}${insightPanel(records,selection)}${activeArchive===null?moodHistory():''}<div class="journey-tools">${button(icon('download')+L('Drucken / als PDF speichern','Print / save as PDF'),'print-journey','button secondary')}${button(L('Alle Einträge sichern','Back up all entries'),'backup','text-link')}${button(L('Diesen Durchlauf sichern','Back up this round'),'backup-round','text-link')}</div><div class="journal-list">${cards}</div>`:`${moodHistory()}<div class="card empty-state">${icon('book')}<h2>${L('Hier wächst deine Reise.','Your journey grows here.')}</h2><p>${L('Sobald du einen Check-in bestätigst oder Gedanken notierst, findest du sie an dieser Stelle wieder.','When you confirm a check-in or write your thoughts, you will find them here.')}</p>${goButton(L('Zu meinem heutigen Tag','Go to my day'),'today','button primary')}</div>`}`;}
  function renderSummary(){return `<section class="summary-hero"><div class="milestone-seal">${icon('leaf')}<strong>${ids().length}</strong><small>${L('TAGE','DAYS')}</small></div><span class="eyebrow">${L('DEIN ABSCHLUSS','YOUR COMPLETION')}</span><h1>${L('Du hast dir diese Zeit gegeben.','You gave yourself this time.')}</h1><p class="lead">${L('Dein Programm ist abgeschlossen. Nimm dir einen Moment für das, was du erlebt hast und was du weitertragen möchtest.','Your program is complete. Take a moment for what you experienced and what you want to carry forward.')}</p>${button(icon('download')+L('Mein Zertifikat','My certificate'),'certificate','button primary')}</section>${discoveryCollection(state.days)}${toolbox()}${insightPanel(state.days,ids())}<div class="summary-actions">${goButton(L('Alle Einträge ansehen','See all entries'),'journey','button secondary')}${button(L('Meine Reise sichern','Back up my journey'),'backup','button secondary')}</div><section class="card next-chapter"><span class="eyebrow">${L('WENN DU WEITERGEHEN MÖCHTEST','IF YOU WOULD LIKE TO CONTINUE')}</span><h2>${L('Deine nächsten Möglichkeiten.','Your next possibilities.')}</h2><p>${L('Du kannst deine Übungen wiederholen, einen neuen Durchlauf beginnen oder persönliche Begleitung entdecken.','Repeat your practices, begin a new round or explore personal guidance.')}</p><div class="link-row">${!C.entitlements(state).bonus?extensionLink():''}<a class="text-link" href="https://sashandventures.com/coaching" target="_blank" rel="noopener noreferrer">${L('Persönliche Begleitung','Personal guidance')} ↗</a>${goButton(L('Neuen Durchlauf vorbereiten','Prepare a new round'),'settings','text-link')}</div></section>`;}
  function renderSettings(){const rights=C.entitlements(state);return `<section class="page-intro"><span class="eyebrow">${L('DEIN RAHMEN','YOUR SPACE')}</span><h1>${L('So passt es zu dir.','Make this space yours.')}</h1><p>${L('Sprache, Darstellung und deine persönlichen Daten an einem Ort.','Language, appearance and your personal data, all in one place.')}</p></section>${recovery?`<section class="card recovery"><h2>${L('Datenrettung','Data recovery')}</h2><p>${L('Der bisherige Speicher ist unverändert erhalten. Lade zuerst die Originaldaten herunter. Du kannst eine gültige Sicherung einlesen oder danach einen neuen Speicher beginnen.','The existing data is preserved unchanged. Download it first. You can restore a valid backup or then begin with fresh storage.')}</p>${button(L('Originaldaten herunterladen','Download original data'),'raw-backup','button secondary')}${button(L('Neuen Speicher vorbereiten','Prepare fresh storage'),'recover-fresh','text-link')}</section>`:''}<div class="settings-grid"><section class="card"><h2>${L('Persönlich','Personal')}</h2><div class="form-field"><label for="settings-name">${L('Dein Name, freiwillig','Your name, optional')}</label><input id="settings-name" data-setting="name" maxlength="40" autocomplete="given-name" value="${esc(state.settings.name)}"><p class="small">${L('So erscheint dein Name auf dem Zertifikat.','This is how your name appears on your certificate.')}</p></div><div class="form-field"><label for="language-select">${L('Sprache','Language')}</label><select id="language-select" data-setting="language"><option value="de" ${state.settings.language==='de'?'selected':''}>Deutsch</option><option value="en" ${state.settings.language==='en'?'selected':''}>English</option></select></div><div class="form-field"><label for="theme-select">${L('Darstellung','Appearance')}</label><select id="theme-select" data-setting="theme">${[['system',L('Wie mein Gerät','Match my device')],['light',L('Hell','Light')],['dark',L('Dunkel','Dark')]].map(([v,label])=>`<option value="${v}" ${state.settings.theme===v?'selected':''}>${label}</option>`).join('')}</select></div><div class="form-field"><label for="writing-select">${L('Bei den Übungen schreibe ich …','During practice, I write …')}</label><select id="writing-select" data-setting="writingMode"><option value="app" ${state.settings.writingMode==='app'?'selected':''}>${L('in der App','in the app')}</option><option value="paper" ${state.settings.writingMode==='paper'?'selected':''}>${L('auf Papier','on paper')}</option></select></div></section><section class="card"><h2>${L('Zugang & Installation','Access & installation')}</h2><p>${rights.core?L('Kerntage 1–7 freigeschaltet.','Core days 1–7 unlocked.'):L('Kerntage 1–7: zusätzlicher Zugang.','Core days 1–7: additional access.')}</p><p>${rights.bonus?L('Vertiefung 8–10 freigeschaltet.','Days 8–10 unlocked.'):L('Vertiefung 8–10: zusätzlicher Zugang.','Days 8–10: additional access.')}</p>${button(L('Weiteren Code eingeben','Enter another access code'),'add-code','button secondary')}${button(L('App auf dem Gerät installieren','Install app on this device'),'install','button secondary')}<p class="small"><span id="connection-label">${navigator.onLine?L('Online','Online'):L('Offline','Offline')}</span> · 7DOC ${window.SevenUpdates?.VERSION||'2.3'}</p></section><section class="card"><h2>${L('Ein Moment im Kalender','A moment in your calendar')}</h2><p>${L('Wähle eine Zeit und lade Termine für deine noch offenen Programmtage herunter. Die Erinnerung wird von deiner Kalender-App verwaltet.','Choose a time and download events for your remaining program days. Your calendar app manages the reminder.')}</p><div class="form-field"><label for="reminder-time">${L('Meine bevorzugte Zeit','My preferred time')}</label><input type="time" id="reminder-time" data-setting="reminderTime" value="${state.settings.reminderTime}"></div>${button(L('Kalender-Erinnerung herunterladen','Download calendar reminder'),'calendar','button secondary',`${C.remaining(state)?'':'disabled'}`)}<p class="small">${L('Die Termine wiederholen sich täglich. Änderungen und Pausen verwaltest du im Kalender. Bereits angelegte Termine bleiben dort bestehen.','Events repeat daily. Manage changes and pauses in your calendar. Previously added events remain there.')}</p></section><section class="card"><h2>${L('Sicherung & Wiederherstellung','Backup & restore')}</h2><p>${L('Deine Einträge liegen in diesem Browser. Sichere sie vor einem Gerätewechsel oder dem Löschen von Browserdaten. Die Datei enthält persönliche Texte: Bewahre sie geschützt auf.','Your entries are stored in this browser. Back them up before changing devices or clearing browser data. The file contains personal writing: keep it private.')}</p>${button(icon('download')+L('Sicherungsdatei herunterladen','Download backup file'),'backup','button secondary')}<label class="button secondary file-button" for="backup-file">${L('Sicherung wiederherstellen','Restore backup')}</label><input type="file" id="backup-file" accept="application/json,.json" hidden><p class="small">${L('Enthält alle Einträge und archivierten Durchläufe. Dein Zugang auf diesem Gerät bleibt beim Import erhalten.','Includes all entries and archived rounds. Import preserves the access on this device.')}</p></section><section class="card"><h2>${L('Offline nutzen','Use offline')}</h2><p>${L('Nach dem ersten erfolgreichen Laden kann die App offline starten. Speichere jedes gewünschte Audio in seiner Tagespraxis ausdrücklich offline. Prüfe die Wiedergabe vor einer Reise im Flugmodus.','After a successful first load, the app can start offline. Explicitly save each audio from its practice page. Before travelling, check playback in airplane mode.')}</p><p id="offline-settings-status" class="small">${offlineDays.size} ${L('Audios in dieser Sprache gespeichert','audio files saved in this language')}</p>${button(L('Gespeicherte Audios entfernen','Remove saved audio'),'clear-audio','button secondary')}</section><section class="card"><h2>${L('Deine Daten & Privatsphäre','Your data & privacy')}</h2><p>${L('Diese Version lädt Schriften und Programmlogik vom App-Host. Deine Notizen, Bewertungen und dein Name werden durch die App auf diesem Gerät gespeichert.','This version loads fonts and app code from the app host. The app stores your notes, ratings and name on this device.')}</p><p>${L('Automatische Push-Nachrichten sind in dieser Version deaktiviert. Kalendertermine richtest du selbst ein. Externe Links öffnen die jeweilige Website mit ihren eigenen Datenschutzregeln.','Automatic push notifications are disabled in this version. You set up calendar events yourself. External links open websites with their own privacy practices.')}</p><a href="https://sashandventures.com" target="_blank" rel="noopener noreferrer" class="text-link">${L('Kontakt & Anbieterinformationen','Contact & provider information')} ↗</a></section><section class="card settings-wide"><h2>${L('Ein neuer Durchlauf','A new round')}</h2><p>${L('Dein aktueller Durchlauf wird archiviert. Du kannst ihn anschließend unter „Meine Reise“ wieder ansehen. Dein Zugang und deine Einstellungen bleiben erhalten.','Your current round will be archived. You can revisit it in My journey. Your access and settings stay with you.')}</p>${button(L('Durchlauf archivieren und neu beginnen','Archive round and begin again'),'restart','button secondary')}<details class="danger-zone"><summary>${L('Alle App-Daten von diesem Gerät entfernen','Remove all app data from this device')}</summary><p>${L('Das entfernt Einträge, Archive, Einstellungen und Zugangsdaten aus diesem Browser. Lade vorher eine Sicherung herunter und halte deinen Zugangscode bereit.','This removes entries, archives, settings and access from this browser. Download a backup first and keep your access code.')}</p>${button(L('Datenlöschung vorbereiten','Prepare data deletion'),'delete','button danger')}</details></section></div>`;}
  function openDialog(title,body){pauseBreath();pauseActivation();const d=$('#dialog');if(!d.open)dialogReturn=document.activeElement;if(d.open)d.close();d.innerHTML=`<div class="dialog-heading"><h2 id="dialog-title">${title}</h2>${button(icon('close'),'close-dialog','icon-button',`aria-label="${L('Schließen','Close')}"`)}</div><div class="dialog-body">${body}</div>`;d.showModal();const focus=d.querySelector('input,button:not(.icon-button),select');if(focus)focus.focus();}
  function closeDialog(){if(updateReloadLock)return;pauseBreath();$('#dialog').close();}
  function pauseBreath(){if(breathRunning){breathElapsed=Math.min(50000,breathElapsed+performance.now()-breathStart);breathRunning=false;cancelAnimationFrame(breathFrame);}const b=$('#breath-toggle');if(b)b.textContent=breathElapsed>0&&breathElapsed<50000?L('Fortsetzen','Continue'):L('Starten','Start');}
  function showBreath(){audio?.pause();openDialog(L('Dein Atem. Dein Tempo.','Your breath. Your pace.'),`<p>${L('4 Sekunden einatmen, 6 Sekunden ausatmen. Fünf ruhige Zyklen. Du kannst jederzeit pausieren oder frei weiteratmen.','Breathe in for 4 seconds, out for 6. Five calm cycles. Pause at any time or continue at your own pace.')}</p><div class="breath-stage"><div id="breath-orb" class="breath-orb"><span id="breath-count" aria-hidden="true">4</span></div></div><p id="breath-phase" class="breath-phase" role="status">${L('Bereit','Ready')}</p><p id="breath-cycle" class="small text-center">${L('5 Zyklen · 50 Sekunden','5 cycles · 50 seconds')}</p><div class="dialog-actions">${button(breathElapsed>0&&breathElapsed<50000?L('Fortsetzen','Continue'):L('Starten','Start'),'breath-toggle','button primary','id="breath-toggle"')}${button(L('Neu beginnen','Restart'),'breath-reset','button secondary')}</div>`);}
  function tickBreath(){if(!breathRunning)return;const total=breathElapsed+performance.now()-breathStart;if(total>=50000){breathRunning=false;breathElapsed=50000;$('#breath-phase').textContent=L('Die Begleitung ist zu Ende. Lass deinen Atem frei fließen.','The guide is complete. Let your breath flow freely.');$('#breath-count').textContent='✓';$('#breath-orb').style.transform='scale(1)';$('#breath-toggle').textContent=L('Noch einmal','Again');return;}const pos=total%10000,inhale=pos<4000,seconds=Math.ceil((inhale?4000-pos:10000-pos)/1000),p=inhale?pos/4000:1-(pos-4000)/6000;$('#breath-orb').style.transform=`scale(${1+p*.32})`;$('#breath-count').textContent=seconds;const label=inhale?L('Einatmen','Breathe in'):L('Ausatmen','Breathe out');if($('#breath-phase').textContent!==label)$('#breath-phase').textContent=label;$('#breath-cycle').textContent=L('Zyklus ','Cycle ')+(Math.floor(total/10000)+1)+' / 5';breathFrame=requestAnimationFrame(tickBreath);}
  function grounding(){audio?.pause();openDialog(L('Ein Moment zum Orientieren.','A moment to orient yourself.'),`<p>${L('Du darfst die Übung pausieren. Schau dich in Ruhe um und wähle, was sich gerade angenehm anfühlt.','You can pause the practice. Look around gently and choose what feels comfortable right now.')}</p><ol class="grounding-list">${L([['Sehen','Nimm eine Farbe oder eine Form wahr.'],['Hören','Lausche einem Geräusch in deiner Nähe.'],['Spüren','Fühle den Boden oder einen Gegenstand.'],['Riechen','Bemerke einen vertrauten Duft, wenn du magst.'],['Schmecken','Nimm einen Schluck Wasser, wenn es passt.']],[['See','Notice a colour or a shape.'],['Hear','Listen for a sound nearby.'],['Feel','Sense the ground or an object.'],['Smell','Notice a familiar scent, if you like.'],['Taste','Take a sip of water, if that fits.']]).map(([t,p])=>`<li><strong>${t}</strong><span>${p}</span></li>`).join('')}</ol>${button(L('Ich nehme mir weiter Zeit','I will take my time'),'close-dialog','button primary')}`);}
  function resetAudio(){audioDay=null;if(audio){audio.pause();audio.removeAttribute('src');audio.load();}}
  function captureAudio(){if(updateReloadLock)return;if(audio&&audioDay&&Number.isFinite(audio.currentTime)){record(audioDay).audioTime=audio.currentTime;save(false);}}
  function mountAudio(actual){const slot=$('#audio-slot');if(!slot||!actual.startsWith('day')){audio?.pause();return;}const n=Number(actual.slice(3));if(!audio){audio=document.createElement('audio');audio.controls=true;audio.preload='none';audio.setAttribute('playsinline','');audio.addEventListener('error',()=>{const e=$('#audio-error');if(e)e.innerHTML=esc(L('Das Audio ist gerade nicht erreichbar. Prüfe deine Verbindung oder den Offline-Download und versuche es erneut.','This audio is currently unavailable. Check your connection or offline download, then try again.'));});audio.addEventListener('loadedmetadata',()=>{if(!audioDay)return;const r=record(audioDay);if(r.audioTime>0&&r.audioTime<audio.duration)audio.currentTime=r.audioTime;const e=$('#audio-duration');if(e&&Number.isFinite(audio.duration))e.textContent=Math.floor(audio.duration/60)+':'+String(Math.floor(audio.duration%60)).padStart(2,'0')+' · '+L('Audio-Impuls','Audio companion');});audio.addEventListener('timeupdate',()=>{if(Date.now()-lastAudioSave>5000){captureAudio();lastAudioSave=Date.now();}});audio.addEventListener('pause',captureAudio);audio.addEventListener('ended',()=>{if(audioDay){record(audioDay).audioTime=0;save(false);}});}
    const source=new URL(audioPath(n),location.href).href;if(audio.src!==source){captureAudio();audio.pause();audioDay=n;audio.src=source;}slot.append(audio);audio.setAttribute('aria-label',dayLabel(n)+' · '+L('Audio','Audio'));}
  function audioPath(n){return `./audio/${state.settings.language}/audio-tag-${n}-${state.settings.language}.mp3`;}
  async function refreshOffline(){offlineDays.clear();try{if('caches'in window){const cache=await caches.open('7doc-media-v2');for(const n of ids())if(await cache.match(new URL(audioPath(n),location.href).href))offlineDays.add(n);}}catch{/* offline status is advisory */}const s=$('#offline-settings-status');if(s)s.textContent=offlineDays.size+' '+L('Audios in dieser Sprache gespeichert','audio files saved in this language');}
  async function downloadAudio(n){if(offlineBusy)return;if(!('caches'in window)||!navigator.serviceWorker?.controller){toast(L('Die Offline-Funktion wird vorbereitet. Öffne die App online erneut und versuche es dann noch einmal.','Offline support is being prepared. Reopen the app online, then try again.'));return;}offlineBusy=true;const lang=state.settings.language,url=new URL(audioPath(n),location.href).href,bar=$('#download-progress'),statusEl=$('#download-status');if(bar){bar.hidden=false;bar.removeAttribute('value');}if(statusEl)statusEl.textContent=L('Audio wird vollständig geladen …','Downloading the complete audio …');try{const response=await fetch(url,{cache:'no-store'});if(!response.ok||response.status!==200||!/^(audio\/|application\/octet-stream)/i.test(response.headers.get('content-type')||''))throw new Error('Audio unavailable');const blob=await response.blob();if(!blob.size)throw new Error('Empty audio');const cache=await caches.open('7doc-media-v2');await cache.put(url,new Response(blob,{headers:{'Content-Type':response.headers.get('content-type')||'audio/mpeg','Content-Length':String(blob.size)}}));if(lang===state.settings.language){offlineDays.add(n);const label=accessibleRoute()==='day'+n?$('#offline-label'):null;if(label)label.textContent=L('Offline gespeichert','Saved offline');}if(statusEl?.isConnected)statusEl.textContent=L('Vollständig gespeichert · ','Fully saved · ')+(blob.size/1024/1024).toFixed(1)+' MB';toast(L('Audio ist für offline gespeichert.','Audio saved for offline use.'));}catch{if(statusEl?.isConnected)statusEl.textContent=L('Der Download hat nicht geklappt. Prüfe Verbindung, Speicherplatz und Audiodatei. Du kannst es erneut versuchen.','The download did not finish. Check your connection, free space and the audio file. You can try again.');}finally{offlineBusy=false;if(bar?.isConnected)bar.hidden=true;document.querySelectorAll('[data-action=download-audio]').forEach(b=>b.disabled=false);}}
  function download(name,blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
  function backup(single=false){try{const data=single?C.backupRound(state,activeArchive):state;const json=C.serializeBackup(data);download('7DOC-Sicherung-'+(single?'Durchlauf-':'')+C.localDate()+'.json',new Blob([json],{type:'application/json'}));toast(L('Sicherungsdatei ist zum Download bereit.','Backup file is ready to download.'));}catch{toast(L('Diese Gesamtsicherung ist zu groß. Sichere die Durchläufe einzeln unter Meine Reise.','This full backup is too large. Back up individual rounds in My journey.'));}}
  function printJourney(){const a=activeArchive===null?null:state.archives[activeArchive],records=a?.days||state.days;let sheet=$('#print-sheet');if(sheet)sheet.remove();sheet=document.createElement('section');sheet.id='print-sheet';sheet.innerHTML=`<h1>7 Days of Change</h1><h2>${L('Meine Reise','My journey')}</h2><p>${esc(state.settings.name)} · ${C.localDate()}</p>${records.map((r,i)=>{const entries=Object.entries(r.notes).filter(([k,v])=>k!=='ix_state'&&v.trim());if(!entries.length&&!r.ratings&&!r.legacyRatings&&!r.completed&&!r.value)return '';return `<article><h2>${dayLabel(i+1)} · ${esc(day(i+1).title)}</h2><p>${status(r)}</p>${r.ratings?`<p>${C.METRICS.map((k,j)=>metricNames()[j]+': '+r.ratings[k]+'/10').join(' · ')}</p>`:''}${r.legacyRatings?`<p>${L('Übernommene Werte','Preserved ratings')}: ${C.METRICS.map((k,j)=>metricNames()[j]+': '+r.legacyRatings[k]+'/10').join(' · ')}</p>`:''}${r.value?`<p>${L('Mein Wert','My value')}: ${esc(r.value)}</p>`:''}${entries.map(([k,v])=>`<h3>${esc(noteLabel(i+1,k))}</h3><p class="print-note">${esc(v)}</p>`).join('')}</article>`;}).join('')}`;document.body.append(sheet);window.print();}
  async function certificate(){if(!C.allComplete(state)){toast(L('Dein Zertifikat wird nach allen Tagen deines Programms verfügbar.','Your certificate becomes available after all days of your program are complete.'));return;}openDialog(L('Dein Zertifikat','Your certificate'),`<p>${L('Es würdigt die Zeit, die du dir für dein Programm genommen hast.','A reminder of the time you gave yourself for your program.')}</p><form id="certificate-form"><label for="certificate-name">${L('Name auf dem Zertifikat','Name on your certificate')}</label><input id="certificate-name" name="name" maxlength="40" value="${esc(state.settings.name)}" placeholder="${L('Dein Name, freiwillig','Your name, optional')}"><div class="dialog-actions"><button class="button primary" type="submit">${L('Als Bild herunterladen','Download as image')}</button></div></form>`);}
  function drawCertificate(name){const canvas=document.createElement('canvas');canvas.width=1600;canvas.height=1120;const x=canvas.getContext('2d');x.fillStyle='#FAF8F3';x.fillRect(0,0,1600,1120);x.strokeStyle='#A8593D';x.lineWidth=2;x.strokeRect(58,58,1484,1004);x.strokeStyle='#B49A70';x.strokeRect(72,72,1456,976);x.textAlign='center';x.fillStyle='#775C35';x.font='20px sans-serif';x.fillText('SASH & VENTURES',800,175);x.fillStyle='#2C2824';x.font='60px Georgia';x.fillText(L('Ein Moment für dich.','A moment for yourself.'),800,300);let size=82;x.font=`italic ${size}px Georgia`;while(x.measureText(name||L('Für dich','For you')).width>1250&&size>26)x.font=`italic ${--size}px Georgia`;x.fillText(name||L('Für dich','For you'),800,475);x.font='27px sans-serif';x.fillStyle='#5C5650';x.fillText(L('hat das persönliche Programm abgeschlossen','has completed the personal program'),800,555);x.fillStyle='#A8593D';x.font='54px Georgia';x.fillText('7 Days of Change',800,665);x.font='25px sans-serif';x.fillStyle='#5C5650';x.fillText(ids().length+' '+L('Tage · Raum für Atem, Praxis und Reflexion','days · Space for breath, practice and reflection'),800,730);const last=ids().map(n=>record(n).completedAt).filter(Boolean).sort().at(-1);x.font='22px sans-serif';x.fillText('Sascha Böhme · '+(last?new Date(last):new Date()).toLocaleDateString(state.settings.language==='de'?'de-DE':'en-GB'),800,925);x.font='18px sans-serif';x.fillText(L('Eine persönliche Erinnerung an deinen Weg.','A personal reminder of your journey.'),800,975);canvas.toBlob(blob=>{if(blob){download('7DOC-Zertifikat.png',blob);toast(L('Dein Zertifikat ist bereit.','Your certificate is ready.'));}else toast(L('Bitte versuche den Download erneut.','Please try the download again.'));},'image/png');}
  async function handleSubmit(e){
    if(e.target.id==='code-form'){
      e.preventDefault();const input=e.target.elements.code,code=input.value.trim().toLowerCase(),err=$('#code-error'),btn=e.target.querySelector('button[type=submit]');if(!code)return;btn.disabled=true;
      try{if(!crypto.subtle)throw new Error('HTTPS');const raw=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(code));const hash=Array.from(new Uint8Array(raw),b=>b.toString(16).padStart(2,'0')).join('');
        if(!Object.values(C.HASHES).includes(hash)||hash===C.HASHES.legacyBundle){err.textContent=L('Prüfe den Code bitte noch einmal. Du findest ihn in deiner Kaufbestätigung.','Please check your code again. Find it in your purchase confirmation.');input.focus();return;}
        if(!state.access.codes.includes(hash))state.access.codes.push(hash);if(!save(false)){err.textContent=L('Der Zugang wurde erkannt. Der Gerätespeicher ist gerade nicht verfügbar.','Your access code was recognised. Device storage is currently unavailable.');return;}
        if($('#dialog').open)closeDialog();navigate('today');render();toast(L('Dein Zugang ist bereit. Schön, dass du hier bist.','Your access is ready. Welcome.'));
      }catch{err.textContent=L('Öffne die App über eine sichere HTTPS-Verbindung und versuche es erneut.','Open the app over a secure HTTPS connection and try again.');}finally{if(btn.isConnected)btn.disabled=false;}
    }
    if(e.target.id==='certificate-form'){e.preventDefault();const name=e.target.elements.name.value.trim().slice(0,40);state.settings.name=name;if(save(false)){closeDialog();drawCertificate(name);}}
  }
  function handleInput(e){const el=e.target;if(el.dataset.note){const n=Number(el.dataset.day);if(!ids().includes(n))return;const r=record(n);if(!r.startedAt)r.startedAt=new Date().toISOString();r.notes[el.dataset.note]=el.value;save();}
    if(el.dataset.rating){const n=Number(route?.slice(3));if(!ids().includes(n))return;const r=record(n);r.ratingDraft={...(r.ratingDraft||r.ratings||{a:5,b:5,c:5,d:5}),[el.dataset.rating]:Number(el.value)};save(false);const o=$('#out-'+el.dataset.rating);if(o)o.textContent=el.value;selectedRatings.add(el.dataset.rating);const feedback=$('#rating-feedback');if(feedback)feedback.textContent=L('Änderung noch bestätigen','Confirm to save these changes');}
    if(el.dataset.ixInput){exerciseInput(Number(el.dataset.day),el.dataset.ixInput,el.value);}
    if(el.dataset.valueInput){const n=Number(el.dataset.valueInput);record(n).value=el.value.slice(0,80);save();document.querySelectorAll('.value-options button').forEach(b=>{b.classList.toggle('selected',b.dataset.value===el.value);b.setAttribute('aria-pressed',String(b.dataset.value===el.value));});}
    if(el.dataset.setting==='name'){state.settings.name=el.value.slice(0,40);save(false);}
  }
  async function handleChange(e){const el=e.target;
    if(el.dataset.setting){const k=el.dataset.setting,v=el.value;const allowed={language:['de','en'],theme:['light','dark','system'],writingMode:['app','paper']};if(k==='reminderTime'&&!/^([01]\d|2[0-3]):[0-5]\d$/.test(v))return;if(allowed[k]&&!allowed[k].includes(v))return;if(!['name','language','theme','writingMode','reminderTime'].includes(k))return;captureAudio();state.settings[k]=v;save(false);applyTheme();if(k!=='name'&&k!=='reminderTime'){render(false);refreshOffline();}}
    if(el.id==='archive-select'){activeArchive=el.value==='current'?null:Number(el.value);if(activeArchive!==null&&!state.archives[activeArchive])activeArchive=null;render();}
    if(el.id==='backup-file'){const file=el.files?.[0];if(!file)return;importBusy=true;try{if(file.size>C.MAX_BACKUP_BYTES)throw new Error('Large file');const text=await file.text();importCandidate=C.restore(JSON.parse(text),state);openDialog(L('Sicherung wiederherstellen?','Restore this backup?'),`<p>${L('Die Einträge und Archive dieser Sicherung ersetzen den aktuellen Durchlauf und seine Archive. Dein Zugang auf diesem Gerät bleibt erhalten. Lade vorher deine aktuelle Sicherung herunter.','This backup replaces the current entries and archives. Your access on this device is preserved. Download your current backup first.')}</p><div class="dialog-actions">${button(L('Aktuellen Stand sichern','Back up current state'),'backup','button secondary')}${button(L('Diese Sicherung übernehmen','Restore this backup'),'confirm-import','button primary')}</div>`);}catch{toast(L('Diese Datei ist keine gültige 7DOC-Sicherung oder überschreitet die Größenbegrenzung. Dein aktueller Stand bleibt erhalten.','This is not a valid 7DOC backup or exceeds the size limit. Your current data is preserved.'));}finally{importBusy=false;el.value='';}}
  }
  function setStage(n,s,discard=false){if(!ids().includes(n))return;if(record(n).stage===0&&s!==0&&record(n).ratingDraft&&!discard){openDialog(L('Deinen Check-in übernehmen?','Save your check-in?'),`<p>${L('Deine geänderten Werte sind als Entwurf gespeichert. Möchtest du sie bestätigen?','Your changed values are saved as a draft. Would you like to confirm them?')}</p><div class="dialog-actions">${button(L('Speichern und weiter','Save and continue'),'confirm-checkin','button primary',`data-day="${n}" data-stage="${s}"`)}${button(L('Heute überspringen','Skip today'),'skip-checkin','button secondary',`data-day="${n}" data-stage="${s}"`)}</div>`);return;}pauseActivation();captureAudio();const r=record(n);r.stage=Math.max(0,Math.min(3,s));if(!r.startedAt)r.startedAt=new Date().toISOString();if(r.stage!==1)audio?.pause();save(false);refreshSession(n);}
  async function handleClick(e){const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action,n=Number(b.dataset.day),allowed=ids().includes(n);
    if(['stage','practice-step','short-session','mode','value','save-ratings','confirm-checkin','skip-checkin','complete','undo-complete','download-audio','retry-audio'].includes(action)&&!allowed)return;
    if(action.startsWith('ix-')){if(allowed)await exerciseAction(n,action.slice(3),b.dataset.value||'');return;}
    switch(action){
      case'navigate':navigate(b.dataset.route);break;
      case'language':captureAudio();state.settings.language=state.settings.language==='de'?'en':'de';save(false);render(false);refreshOffline();break;
      case'theme-toggle':state.settings.theme=themeControlData().icon==='sun'?'light':'dark';save(false);applyTheme();{const select=$('#theme-select');if(select)select.value=state.settings.theme;}break;
      case'add-code':openDialog(L('Deinen Zugang ergänzen','Add to your access'),codeForm());break;
      case'close-dialog':closeDialog();break;
      case'grounding':grounding();break;
      case'mood':{state.moods[C.localDate()]=Number(b.dataset.mood);const ok=save(false);document.querySelectorAll('.mood-options button').forEach(el=>{el.classList.toggle('selected',el===b);el.setAttribute('aria-pressed',String(el===b));});toast(ok?L('Deine Momentaufnahme ist gespeichert.','Your snapshot is saved.'):L('Die Auswahl ist noch nicht auf diesem Gerät gespeichert. Sichere deine Einträge.','This selection has not been saved on this device. Back up your entries.'));break;}
      case'breath':showBreath();break;
      case'breath-toggle':if(breathRunning){pauseBreath();}else{if(breathElapsed>=50000)breathElapsed=0;breathStart=performance.now();breathRunning=true;b.textContent=L('Pausieren','Pause');breathFrame=requestAnimationFrame(tickBreath);}break;
      case'breath-reset':pauseBreath();breathElapsed=0;showBreath();break;
      case'stage':setStage(n,Number(b.dataset.stage));break;
      case'practice-step':pauseActivation();record(n).practiceStep=Number(b.dataset.step);save(false);refreshSession(n);break;
      case'short-session':record(n).mode='short';record(n).stage=1;if(!record(n).startedAt)record(n).startedAt=new Date().toISOString();save(false);navigate('day'+n);break;
      case'mode':pauseActivation();record(n).mode=b.dataset.mode==='short'?'short':'full';save(false);refreshSession(n);break;
      case'value':record(n).value=b.dataset.value;save();document.querySelectorAll('.value-options button').forEach(el=>{el.classList.toggle('selected',el===b);el.setAttribute('aria-pressed',String(el===b));});$('#day-value').value=record(n).value;break;
      case'confirm-checkin':case'save-ratings':{const vals=Object.fromEntries(C.METRICS.map(k=>[k,Number($('#rating-'+k).value)]));record(n).ratings=vals;record(n).ratingDraft=null;record(n).measuredAt=new Date().toISOString();if(!record(n).startedAt)record(n).startedAt=record(n).measuredAt;if(save(false)){$('#rating-feedback').textContent=L('Check-in gespeichert','Check-in saved');selectedRatings.clear();toast(L('Dein Check-in ist gespeichert.','Your check-in is saved.'));if(action==='confirm-checkin'){closeDialog();setStage(n,Number(b.dataset.stage),true);}} break;}
      case'skip-checkin':record(n).ratingDraft=null;save(false);selectedRatings.clear();closeDialog();setStage(n,Number(b.dataset.stage),true);break;
      case'complete':{const r=record(n),previous={completed:r.completed,completedAt:r.completedAt};r.completed=true;if(!r.completedAt)r.completedAt=new Date().toISOString();if(save(false)){refreshSession(n);toast(C.allComplete(state)?L('Dein Programm ist abgeschlossen. Dein Rückblick ist bereit.','Your program is complete. Your reflection is ready.'):L('Dein Tag ist abgeschlossen.','Your day is complete.'));}else Object.assign(r,previous);break;}
      case'undo-complete':{const r=record(n),previous={completed:r.completed,completedAt:r.completedAt};r.completed=false;r.completedAt=null;if(save(false)){refreshSession(n);toast(L('Der Tagesabschluss ist zurückgenommen.','Day completion undone.'));}else Object.assign(r,previous);break;}
      case'download-audio':await downloadAudio(n);break;
      case'retry-audio':if(audio){captureAudio();$('#audio-error').textContent='';audio.load();}break;
      case'backup':backup();break;
      case'backup-round':backup(true);break;
      case'archive-remove':if(activeArchive!==null&&state.archives[activeArchive])openDialog(L('Dieses Archiv entfernen?','Remove this archive?'),`<p>${L('Sichere diesen Durchlauf zuerst als Datei. Anschließend kannst du genau dieses Archiv vom Gerät entfernen. Der aktuelle Durchlauf bleibt erhalten.','Back up this round first. You can then remove this archive from the device. Your current round is preserved.')}</p><div class="dialog-actions">${button(L('Durchlauf sichern','Back up round'),'backup-round','button secondary')}${button(L('Dieses Archiv entfernen','Remove this archive'),'confirm-remove-archive','button danger')}</div>`);break;
      case'confirm-remove-archive':if(activeArchive!==null&&state.archives[activeArchive]){const previous=structuredClone(state.archives);state.archives.splice(activeArchive,1);if(save(false)){activeArchive=null;closeDialog();render();toast(L('Dieses Archiv wurde entfernt.','This archive was removed.'));}else state.archives=previous;}break;
      case'print-journey':printJourney();break;
      case'certificate':certificate();break;
      case'calendar':try{download('7DOC-Erinnerung.ics',new Blob([C.calendar(state)],{type:'text/calendar;charset=utf-8'}));toast(L('Öffne die Datei in deiner Kalender-App. Prüfe dort Termine und Benachrichtigungen.','Open the file in your calendar app. Check the events and notifications there.'));}catch{toast(L('Dein Programm ist bereits abgeschlossen.','Your program is already complete.'));}break;
      case'install':await install();break;
      case'confirm-import':if(importCandidate){const previous=state,previousRecovery=recovery;state=importCandidate;recovery=null;if(save(false)){resetAudio();importCandidate=null;activeArchive=null;closeDialog();applyTheme();navigate('today');render();toast(L('Deine Sicherung ist wiederhergestellt.','Your backup is restored.'));}else{state=previous;recovery=previousRecovery;}}break;
      case'restart':if(state.archives.length>=20){toast(L('Dein Archiv enthält 20 Durchläufe. Sichere deine Daten, bevor du Einträge entfernst.','Your archive contains 20 rounds. Back up your data before removing entries.'));break;}openDialog(L('Einen neuen Durchlauf beginnen?','Begin a new round?'),`<p>${L('Deine bisherigen Einträge kommen ins Archiv und bleiben unter „Meine Reise“ erreichbar. Deine Einstellungen und dein Zugang bleiben erhalten.','Your entries move to the archive and remain available in My journey. Your settings and access are preserved.')}</p><div class="dialog-actions">${button(L('Vorher eine Sicherung laden','Download a backup first'),'backup','button secondary')}${button(L('Archivieren und beginnen','Archive and begin'),'confirm-restart','button primary')}</div>`);break;
      case'confirm-restart':{const before=structuredClone(state);captureAudio();audio?.pause();state.archives.push({endedAt:new Date().toISOString(),name:state.settings.name,days:structuredClone(state.days)});state.days=Array.from({length:10},C.blankDay);if(save(false)){resetAudio();activeArchive=null;closeDialog();navigate('today');render();toast(L('Dein neuer Durchlauf ist bereit.','Your new round is ready.'));}else state=before;break;}
      case'delete':openDialog(L('Alle App-Daten entfernen?','Remove all app data?'),`<p>${L('Das löscht deine Einträge, Archive, Einstellungen und deinen Zugang aus diesem Browser. Du kannst anschließend mit deinem Code und einer Sicherung zurückkehren.','This deletes your entries, archives, settings and access from this browser. You can return with your access code and a backup.')}</p>${button(L('Sicherung herunterladen','Download backup'),'backup','button secondary')}<div class="form-field"><label for="delete-check">${L('Schreibe LÖSCHEN zur Bestätigung','Type DELETE to confirm')}</label><input id="delete-check" autocomplete="off"></div>${button(L('Jetzt alle App-Daten entfernen','Remove all app data now'),'confirm-delete','button danger')}`);break;
      case'confirm-delete':if($('#delete-check').value!==L('LÖSCHEN','DELETE')){toast(L('Gib das Bestätigungswort vollständig ein.','Enter the confirmation word exactly.'));break;}await deleteData();break;
      case'raw-backup':if(recovery)download('7DOC-Originaldaten.json',new Blob([recovery],{type:'application/json'}));break;
      case'recover-fresh':openDialog(L('Mit frischem Speicher beginnen?','Begin with fresh storage?'),`<p>${L('Lade zuerst die Originaldaten herunter. Der neue Speicher ersetzt anschließend den bisher unlesbaren Stand.','Download the original data first. Fresh storage will then replace the unreadable data.')}</p>${button(L('Originaldaten herunterladen','Download original data'),'raw-backup','button secondary')}${button(L('Frischen Speicher verwenden','Use fresh storage'),'confirm-fresh','button primary')}`);break;
      case'confirm-fresh':{const raw=recovery;recovery=null;if(save(false)){closeDialog();render();}else recovery=raw;break;}
      case'clear-audio':openDialog(L('Offline-Audios entfernen?','Remove offline audio?'),`<p>${L('Das gibt Gerätespeicher frei. Deine Notizen und dein Fortschritt bleiben erhalten. Du kannst Audios später erneut herunterladen.','This frees device storage. Your notes and progress stay with you. You can download the audio again later.')}</p>${button(L('Gespeicherte Audios entfernen','Remove saved audio'),'confirm-clear-audio','button secondary')}`);break;
      case'confirm-clear-audio':if(offlineBusy){toast(L('Lass den laufenden Download erst fertig werden.','Let the current download finish first.'));break;}try{await caches.delete('7doc-media-v2');offlineDays.clear();closeDialog();render();toast(L('Offline-Audios wurden entfernt.','Offline audio removed.'));}catch{toast(L('Der Offline-Speicher ist gerade nicht verfügbar.','Offline storage is currently unavailable.'));}break;
      case'apply-update':updateManager?.check(true);break;
      case'dismiss-update':$('#update-notice').hidden=true;break;
    }
  }
  async function deleteData(){if(offlineBusy){toast(L('Bitte warte, bis der Audio-Download beendet ist.','Please wait for the audio download to finish.'));return;}resetAudio();try{const keys=[];for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k?.startsWith('7doc_'))keys.push(k);}for(const k of keys)localStorage.removeItem(k);try{for(let i=sessionStorage.length-1;i>=0;i--){const k=sessionStorage.key(i);if(k?.startsWith('7doc_'))sessionStorage.removeItem(k);}}catch{}if('caches'in window)await caches.delete('7doc-media-v2');state=C.fresh();recovery=null;activeArchive=null;offlineDays.clear();closeDialog();applyTheme();navigate('today');render();toast(L('Die App-Daten wurden von diesem Browser entfernt.','App data was removed from this browser.'));}catch{storageOK=false;storageWarning();toast(L('Die Daten konnten nicht vollständig entfernt werden. Prüfe die Browsereinstellungen.','Data could not be fully removed. Check browser settings.'));}}
  async function install(){const standalone=matchMedia('(display-mode: standalone)').matches||navigator.standalone;if(standalone){toast(L('Du nutzt die App bereits als installierte Web-App.','You are already using the installed web app.'));return;}if(newInstallPrompt){await newInstallPrompt.prompt();newInstallPrompt=null;return;}openDialog(L('Deine App auf dem Homescreen','Your app on the home screen'),`<p>${L('So findest du deinen täglichen Moment schnell wieder.','Keep your daily moment close.')}</p><h3>iPhone / iPad</h3><ol><li>${L('Öffne die App in Safari.','Open the app in Safari.')}</li><li>${L('Öffne das Teilen-Menü und wähle „Zum Home-Bildschirm“.','Open the Share menu and choose Add to Home Screen.')}</li><li>${L('Öffne die App anschließend über das neue Symbol.','Then open the app from its new icon.')}</li></ol><h3>Android / Desktop</h3><p>${L('Öffne das Browsermenü und wähle „App installieren“ oder „Zum Startbildschirm hinzufügen“, sofern angeboten.','Open the browser menu and choose Install app or Add to Home screen, when available.')}</p><p class="small">${L('Sichere deine Einträge vor einem Wechsel zwischen Browser und installierter App. Der verwendete Speicher kann je nach Gerät unterschiedlich sein.','Back up your entries before switching between the browser and installed app. Storage may differ by device.')}</p>`);}
  function updateIsSafe(){
    const focused=document.activeElement;
    return !updateReloadLock&&!recovery&&storageOK&&!offlineBusy&&!importBusy&&!breathRunning&&!activationRunning&&!(audio&&!audio.paused)&&!$('#dialog').open&&!focused?.matches?.('input,textarea,select,[contenteditable="true"],[contenteditable=""]');
  }
  function prepareForUpdate(){
    if(!updateIsSafe())return false;
    // All edits save synchronously. Validate the latest shared record without
    // writing this tab's possibly stale in-memory copy over another tab's work.
    try{const raw=localStorage.getItem(C.KEY);if(!raw)return false;C.normalize(JSON.parse(raw));}catch{return false;}
    const dialog=$('#dialog');dialogReturn=document.activeElement;
    try{
      updateReloadLock=true;dialog.dataset.updateLock='true';
      dialog.innerHTML=`<div class="dialog-heading"><h2 id="dialog-title">${L('Deine App wird aktualisiert.','Updating your app.')}</h2></div><div class="dialog-body"><p>${L('Die neue Version wird übernommen. Gleich geht es weiter.','The new version is being applied. You will be back in a moment.')}</p></div>`;
      dialog.showModal();return true;
    }catch{updateReloadLock=false;delete dialog.dataset.updateLock;return false;}
  }
  function unlockAfterUpdate(){
    updateReloadLock=false;const dialog=$('#dialog');
    if(dialog.dataset.updateLock){delete dialog.dataset.updateLock;if(dialog.open)dialog.close();}
  }
  function showReleaseNote(){
    if(releaseShown||!ids().length||!updateIsSafe())return;
    const build=window.SevenUpdates?.BUILD_ID;if(!build)return;
    try{if(localStorage.getItem('7doc_release_seen')===build){releaseShown=true;return;}}catch{return;}
    releaseShown=true;
    try{localStorage.setItem('7doc_release_seen',build);}catch{/* At most once during this visit if optional metadata cannot be saved. */}
    openDialog(L('Es gibt Neues in deiner App.','There is something new in your app.'),`<div class="release-note"><span class="eyebrow">${L('AKTUALISIERUNG','UPDATE')} · ${window.SevenUpdates.VERSION}</span><p>${L('Diese Version bringt Verbesserungen an Bedienung, Darstellung oder Funktionen mit.','This version brings improvements to the interface, appearance or features.')}</p><p>${L('Du kannst an deinem bisherigen Stand weitergehen. Künftige Updates werden automatisch übernommen, sobald alle geöffneten App-Ansichten dafür bereit sind.','Continue where you left off. Future updates will be applied automatically when all open app views are ready.')}</p>${button(L('Weiter zur App','Continue to the app'),'close-dialog','button primary')}</div>`);
  }
  async function setupWorker(){
    if(!window.SevenUpdates)return;
    updateManager=window.SevenUpdates.create({safe:updateIsSafe,prepare:prepareForUpdate,unlock:unlockAfterUpdate,reload:()=>location.reload(),idle:showReleaseNote,status:value=>{
      const notice=$('#update-notice');
      if(value==='queued'){notice.hidden=false;notice.innerHTML=`<span>${icon('download')}${L('Ein Update ist bereit. Es wird automatisch übernommen, sobald alle App-Ansichten dafür bereit sind.','An update is ready. It will be applied automatically when all app views are ready.')}</span>`;}
      else if(value==='applying'||value==='unavailable')notice.hidden=true;
    }});
    await updateManager.start();
  }
  function renderAudioPanel(n){return `<section id="session-audio-panel" class="audio-card" ${record(n).stage!==1?'hidden':''}><div class="audio-heading">${icon('audio')}<div><h3>${L('Dein Audio-Impuls','Your audio companion')}</h3><p class="small" id="audio-duration">${L('Ca. 4 Minuten · höre zuerst hinein','About 4 minutes · listen first')}</p></div><span class="offline-label" id="offline-label">${offlineDays.has(n)?L('Offline gespeichert','Saved offline'):''}</span></div><div id="audio-slot"></div><p id="audio-error" class="field-error" role="status"></p><div class="audio-actions">${button(icon('download')+L('Audio offline speichern','Save audio offline'),'download-audio','text-link',`data-day="${n}" ${offlineBusy?'disabled':''}`)}${button(L('Audio neu laden','Reload audio'),'retry-audio','text-link',`data-day="${n}"`)}</div><progress id="download-progress" aria-label="${L('Audio-Download','Audio download')}" hidden></progress><p id="download-status" role="status"></p></section>`;}
  function sessionControls(n){const r=record(n),full=r.stage===1&&r.mode!=='short',back=full&&r.practiceStep>0?button(icon('back')+L('Zurück','Back'),'practice-step','button secondary',`data-step="${r.practiceStep-1}" data-day="${n}"`):r.stage?button(icon('back')+L('Zurück','Back'),'stage','button secondary',`data-stage="${r.stage-1}" data-day="${n}"`):goButton(L('Für heute pausieren','Pause for today'),'today','button secondary');const next=full&&r.practiceStep<2?button(L('Nächster Schritt','Next step')+icon('arrow'),'practice-step','button primary',`data-step="${r.practiceStep+1}" data-day="${n}"`):r.stage<3?button(L('Weiter: ','Next: ')+stages()[r.stage+1]+icon('arrow'),'stage','button primary',`data-stage="${r.stage+1}" data-day="${n}"`):'';return back+next;}
  function refreshSession(n){if(accessibleRoute()!=='day'+n){render();return;}const r=record(n),body=$('.session-body');if(!body){render();return;}const top=window.scrollY||0;body.innerHTML=[renderArrival,renderPractice,renderReflection,renderClosing][r.stage](n);$('.session-controls').innerHTML=sessionControls(n);$('.phase-navigation').innerHTML=stages().map((name,i)=>button(`<span>${i+1}</span>${name}`,'stage',i===r.stage?'phase active':'phase',`data-stage="${i}" data-day="${n}" ${i===r.stage?'aria-current="step"':''}`)).join('');const panel=$('#session-audio-panel');if(panel)panel.hidden=r.stage!==1;const heading=body.querySelector('h2');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}const bounds=body.getBoundingClientRect?.();const inset=window.innerWidth<641?20:85;window.scrollTo({top:bounds&&bounds.top<inset?Math.max(0,top+bounds.top-inset):top,behavior:'instant'});}
  function refreshExercise(n,message=''){const el=$('#day-exercise');if(el){el.outerHTML=practiceFields(n);const heading=$('#exercise-title');heading?.focus({preventScroll:true});}const status=$('#ix-feedback');if(status)status.textContent=message;if(storageOK&&!recovery)announceSaved();}
  function exerciseInput(n,key,value){if(!ids().includes(n))return;IX.input(n,record(n).notes,key,value);if(n===2){const m=IX.model(record(n).notes);if(m.winner)record(n).value=m.winner;}if(!record(n).startedAt)record(n).startedAt=new Date().toISOString();save();}
  async function exerciseAction(n,action,value){if(action==='timer-toggle'){toggleActivation();return;}const result=IX.act(n,record(n).notes,action,value,state.days,state.settings.language);if(result.error){const status=$('#ix-feedback');if(status)status.textContent=result.error;return;}if(n===2&&result.model.compared&&result.model.winner){record(n).value=result.model.winner;IX.result(record(n).notes,result.model.winner+(record(n).notes.value_action?': '+record(n).notes.value_action:''));}if(!record(n).startedAt)record(n).startedAt=new Date().toISOString();const ok=save(false);refreshExercise(n,ok?L('Auf diesem Gerät gespeichert','Saved on this device'):L('Noch nicht auf diesem Gerät gespeichert. Sichere deine Einträge.','Not yet saved on this device. Back up your entries.'));if(result.copy!==null){try{if(!navigator.clipboard?.writeText)throw new Error('clipboard');await navigator.clipboard.writeText(result.copy);toast(L('Text kopiert. Du entscheidest selbst, wo du ihn verwendest.','Text copied. You choose where to use it.'));}catch{openDialog(L('Dein Text zum Kopieren','Your text to copy'),`<p>${L('Markiere den Text und kopiere ihn über dein Gerät.','Select the text and copy it using your device.')}</p><label for="copy-text">${L('Deine Nachricht','Your message')}</label><textarea id="copy-text" readonly rows="5">${esc(result.copy)}</textarea>`);}}if(result.exportCard)drawDiscoveryCard(n);}
  function toggleActivation(){if(activationRunning){pauseActivation();refreshExercise(3);return;}activationElapsed=Math.min(30000,Number(IX.model(record(3).notes).timerMs)||0);if(activationElapsed>=30000)activationElapsed=0;activationStart=performance.now();activationRunning=true;const button=$('[data-action="ix-timer-toggle"]');if(button)button.textContent=L('Pausieren','Pause');activationFrame=requestAnimationFrame(tickActivation);}
  function tickActivation(){if(!activationRunning)return;const elapsed=activationElapsed+performance.now()-activationStart,el=$('#activation-count');if(el)el.textContent=String(Math.max(0,Math.ceil((30000-elapsed)/1000)));if(elapsed>=30000){activationRunning=false;activationElapsed=30000;IX.patch(record(3).notes,{timerMs:30000});save(false);refreshExercise(3,L('Dein Zeitfenster ist zu Ende.','Your time window is complete.'));return;}activationFrame=requestAnimationFrame(tickActivation);}
  function pauseActivation(){if(!activationRunning)return;activationElapsed=Math.min(30000,activationElapsed+performance.now()-activationStart);activationRunning=false;cancelAnimationFrame(activationFrame);IX.patch(record(3).notes,{timerMs:activationElapsed});save(false);const button=$('[data-action="ix-timer-toggle"]');if(button)button.textContent=L('Fortsetzen','Continue');}
  function discoveryCollection(records,compact=false){const items=IX.collection(records),shown=compact?items.slice(-3):items;if(!shown.length)return '';return `<section class="discovery-collection"><div class="section-heading"><div><span class="eyebrow">${L('DEINE EIGENEN WORTE','YOUR OWN WORDS')}</span><h2>${L('Was du mitnimmst.','What you carry forward.')}</h2></div><span class="small">${items.length} ${L('Fundstücke','discoveries')}</span></div><div class="discovery-grid">${shown.map(x=>`<article><span class="eyebrow">${dayLabel(x.day)}</span><h3>${IX.titles[state.settings.language][x.day-1]}</h3><p>${esc(x.text.slice(0,380))}${x.text.length>380?' …':''}</p></article>`).join('')}</div>${compact?goButton(L('Meine Sammlung ansehen','See my collection'),'journey','text-link'):''}</section>`;}
  function drawDiscoveryCard(n){const r=record(n),m=IX.model(r.notes),text=n===9?r.notes.new_sentence:[r.notes.ix_scene||m.scene,r.notes.future_letter,r.notes.ix_today?L('Mein Schritt heute: ','My step today: ')+r.notes.ix_today:''].filter(Boolean).join('\n\n');if(!text?.trim()){toast(L('Schreibe zuerst deinen eigenen Text in die Karte.','Write your own text in the card first.'));return;}const canvas=document.createElement('canvas');canvas.width=1200;const x=canvas.getContext('2d');x.font='30px sans-serif';const lines=[];for(const paragraph of text.split('\n')){let line='';for(const chunk of paragraph.split(/\s+/)){if(x.measureText(line+' '+chunk).width>940&&line){lines.push(line);line='';}if(x.measureText(chunk).width>940){for(const c of chunk){if(x.measureText(line+c).width>940){lines.push(line);line='';}line+=c;}}else line+=(line?' ':'')+chunk;}lines.push(line);}const limit=75,truncated=lines.length>limit,visible=lines.slice(0,limit);canvas.height=Math.max(900,370+visible.length*45+(truncated?100:0));x.fillStyle='#FAF8F3';x.fillRect(0,0,1200,canvas.height);x.strokeStyle='#D8D1C6';x.strokeRect(44,44,1112,canvas.height-88);x.fillStyle='#A6533C';x.font='22px sans-serif';x.fillText('7 DAYS OF CHANGE',120,130);x.fillStyle='#2C2824';x.font='44px Georgia';x.fillText(n===9?L('Mein Wort an mich','My word to myself'):L('Eine Postkarte an mich','A postcard to myself'),120,210);x.font='30px sans-serif';visible.forEach((line,i)=>x.fillText(line,120,300+i*45));if(truncated){x.font='22px sans-serif';x.fillText(L('Fortsetzung in deinen gespeicherten Einträgen.','Continued in your saved entries.'),120,canvas.height-150);}x.fillStyle='#68655F';x.font='19px sans-serif';x.fillText('Sash & Ventures · '+C.localDate(),120,canvas.height-80);canvas.toBlob(blob=>{if(blob)download(n===9?'7DOC-Mein-Satz.png':'7DOC-Meine-Postkarte.png',blob);else toast(L('Bitte versuche den Bildexport erneut.','Please try the image export again.'));},'image/png');}

  document.addEventListener('DOMContentLoaded',boot);
})();
